 * The newest batch is the first one when refreshing newest-first and the last one
 * otherwise; the oldest batch is the opposite. The open-ended window fix-up below
 * must use these indices instead of the hard-coded 0 / SPI_processed - 1.
 */
const uint64 newest_batch = refresh_newest_first ? 0 : (SPI_processed - 1);
const uint64 oldest_batch = refresh_newest_first ? (SPI_processed - 1) : 0;

